    # ================================================== TÓM TẮT CHƯƠNG 7
    proj = 'import csv\n\ndef doc_bang(ten):\n    with open(ten, encoding="utf-8", newline="") as f:\n        return list(csv.DictReader(f))\n\ndef xep_loai(d):\n    if d >= 8:\n        return "Giỏi"\n    if d >= 6.5:\n        return "Khá"\n    if d >= 5:\n        return "Trung bình"\n    return "Yếu"\n\ndef tinh_tb(r):\n    return (int(r["toan"]) + int(r["van"])) / 2\n\ndef ghi_ket_qua(ds, ten):\n    with open(ten, "w", encoding="utf-8", newline="") as f:\n        w = csv.writer(f)\n        w.writerow(["ten", "tb", "xep_loai"])\n        for r in ds:\n            tb = tinh_tb(r)\n            w.writerow([r["ten"], tb, xep_loai(tb)])\n\nds = doc_bang("diem.csv")\nassert len(ds) == 4\nghi_ket_qua(ds, "ket_qua.csv")\nprint("Đã ghi ket_qua.csv:")\nfor r in doc_bang("ket_qua.csv"):\n    print(r["ten"], r["tb"], r["xep_loai"])\nbest = max(ds, key=tinh_tb)\nprint("Cao nhất:", best["ten"], tinh_tb(best))'
